CREATE TABLE "platform_settings" ("id" UUID NOT NULL,"church_name" TEXT,"church_short_name" TEXT,"website_url" TEXT,"contact_email" TEXT,"phone" TEXT,"address" TEXT,"timezone" TEXT,"default_language" VARCHAR(2),"supported_languages" JSONB,"logo_url" TEXT,"favicon_url" TEXT,"primary_color" TEXT,"secondary_color" TEXT,"footer_text" TEXT,"facebook_url" TEXT,"instagram_url" TEXT,"youtube_url" TEXT,"give_url" TEXT,"service_times" JSONB,"created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updated_at" TIMESTAMP(3) NOT NULL,"updated_by_user_id" UUID,CONSTRAINT "platform_settings_pkey" PRIMARY KEY ("id"));
